svg.script:
(function () {
  const svg = document.documentElement;
  const minX = 250, maxX = 1370, barrelY = 300, barrelH = 118;
  const graduations = document.getElementById('graduations');
  const liquid = document.getElementById('liquid');
  const doseText = document.getElementById('doseText');
  const bigDose = document.getElementById('bigDose');
  const exampleText = document.getElementById('exampleText');
  const slider = document.getElementById('slider');
  const sliderFill = document.getElementById('sliderFill');

  // Create every graduation from 0 through 100.
  for (let i = 0; i <= 100; i++) {
    const x = minX + (i / 100) * (maxX - minX);
    const major = i % 10 === 0;
    const mid = i % 5 === 0 && !major;
    const y1 = major ? 330 : (mid ? 340 : 348);
    const y2 = major ? 286 : 365;

    const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    line.setAttribute('x1', x); line.setAttribute('x2', x);
    line.setAttribute('y1', y1); line.setAttribute('y2', y2);
    line.setAttribute('class', major ? 'tick10' : (mid ? 'tick5' : 'tick'));
    graduations.appendChild(line);

    // Every unit is labeled below the syringe. This keeps the mapping exact.
    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    text.setAttribute('x', x);
    text.setAttribute('y', 448);
    text.setAttribute('class', 'num');
    text.textContent = i;
    graduations.appendChild(text);

    if (major) {
      const t = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      t.setAttribute('x', x);
      t.setAttribute('y', 270);
      t.setAttribute('class', 'major');
      t.textContent = i;
      graduations.appendChild(t);
    }
  }

  let dose = 23;

  function setDose(v) {
    dose = Math.max(0, Math.min(100, Math.round(v)));
    const x = minX + (dose / 100) * (maxX - minX);

    // O amarelo preenche TODO o interior da seringa até a graduação escolhida.
    liquid.setAttribute('x', minX);
    liquid.setAttribute('width', Math.max(0, x - minX));
    const gloss = document.getElementById('liquidGloss');
    if (gloss) {
      gloss.setAttribute('x', minX);
      gloss.setAttribute('width', Math.max(0, x - minX));
    }

    doseText.textContent = dose;
    bigDose.textContent = dose + ' UI';
    exampleText.textContent = 'Para ' + dose + ' UI, o preenchimento amarelo termina na marca ' + dose + '.';
    slider.setAttribute('cx', 470 + (dose / 100) * 290);
    sliderFill.setAttribute('x2', 470 + (dose / 100) * 290);
  }

  document.getElementById('minus').addEventListener('click', () => setDose(dose - 1));
  document.getElementById('plus').addEventListener('click', () => setDose(dose + 1));
  document.getElementById('quick1').addEventListener('click', () => setDose(7));
  document.getElementById('quick2').addEventListener('click', () => setDose(13));
  document.getElementById('quick3').addEventListener('click', () => setDose(23));
  document.getElementById('quick4').addEventListener('click', () => setDose(50));
  document.getElementById('quick5').addEventListener('click', () => setDose(100));

  // Keyboard control when the SVG is focused.
  svg.setAttribute('tabindex', '0');
  svg.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') setDose(dose - 1);
    if (e.key === 'ArrowRight') setDose(dose + 1);
  });

  setDose(23);
})();
